(()=>{
const $=id=>document.getElementById(id),en=document.documentElement.lang==='en',t=(a,b)=>en?b:a,data=window.GreenGoRailTimetable;
const panel=$('live-transit'),drawer=panel.querySelector('.flow-bus-drawer');let mode=null;
const walk=document.createElement('section');walk.className='mode-route-card';walk.id='walkingRoute';walk.hidden=true;
walk.innerHTML=`<p class="eyebrow">WALK / DIRECT TO CLASS</p><h3>${t('步行导航','Walking directions')}</h3><p id="walkingRouteSummary"></p><div class="campus-navigation-actions"><a id="routeWalkDirections" class="primary" target="_blank" rel="noopener">${t('打开步行导航','Open walking directions')} ↗</a><a class="primary" href="https://www.birmingham.ac.uk/contact/campus-map" target="_blank" rel="noopener">${t('大学官方校园导航','Official campus navigation')} ↗</a></div><p>${t('Google Maps 接收当前地图起点与教学楼。实际路径、入口和无障碍通行由外部地图核对。','Google Maps receives the current map origin and building. Verify the actual path, entrance and accessibility in the external map.')}</p>`;
const rail=document.createElement('section');rail.className='mode-route-card';rail.id='trainTimetable';rail.hidden=true;
rail.innerHTML=`<p class="eyebrow">RAIL / SAVED TIMETABLE</p><h3>${t('火车时刻表 → University','Train timetable → University')}</h3><div id="railControls" class="two-col"></div><p id="railDateStatus" role="status"></p><p>${t('计划时刻 · 非实时。英国当地时间。工程、节假日与临时调整可能覆盖常规时刻；不显示实时站台或延误。','Scheduled times · not live. UK local time. Engineering, bank holidays and short-notice changes may override this schedule; no live platforms or delays.')}</p><p id="railTableStatus" role="status"></p><div class="rail-table-scroll"><table><thead><tr><th>${t('出发','Departs')}</th><th>${t('到达 University','University')}</th><th>${t('运营商','Operator')}</th><th>${t('班次','Service')}</th></tr></thead><tbody id="railTableBody"></tbody></table></div><p id="railSelected" role="status"></p><details><summary>${t('来源、适用期与班次注释','Source, validity & service notes')}</summary><p>${t('Network Rail Table 070，2026-05-17 至 2026-12-12。2026-11-08 保存。提供工作日、周六和周日常规时刻。University 原表为停站出发时间（带 a 为到达），此处作为到站参考；未计校园步行时间。每行原表链接可核对班次注释。','Network Rail Table 070, 17 May–12 Dec 2026. Saved 8 Nov 2026. Weekday, Saturday and Sunday schedules. University uses the published station time (departure unless marked a); treat it as an arrival reference. Campus walking is additional. Each source link includes the original service notes.')}</p><a id="railSource" target="_blank" rel="noopener">${t('官方完整时刻表 PDF','Official full timetable PDF')} ↗</a></details><p><a href="https://www.nationalrail.co.uk/" target="_blank" rel="noopener">${t('出行前在 National Rail 核对当前班次','Check current services with National Rail before travel')} ↗</a></p>`;
panel.append(walk,rail);const label=$('railOriginLabel');$('railControls').append(label);label.firstChild.textContent=t('上车站','Boarding station');$('railBoarding').replaceChildren(new Option('Birmingham New Street','Birmingham New Street'),new Option('Five Ways','Five Ways'));
$('railSource').href=data.source;
const filters=document.createElement('div');filters.className='rail-filters';filters.innerHTML=`<label>${t('通勤日期','Travel date')}<input id="railDate" type="date"></label><label>${t('出发时间：从','Departure: from')}<input id="railFromTime" type="time"></label><label>${t('出发时间：至','Departure: until')}<input id="railToTime" type="time"></label><button id="railAllDay" type="button" class="outline">${t('显示全天','Show all day')}</button><p>${t('时间留空时显示全天。按上车站的出发时间筛选；日期与当前通勤行程同步。结束时间应不早于开始时间，跨日请分别选择日期。','Leave times empty for the full day. Filters use departure time at the boarding station; the date stays in sync with the commute. End time must not precede start time; select each date separately for overnight travel.')}</p>`;$('railControls').after(filters);
$('railDate').value=$('commuteDate').value;
$('railDate').addEventListener('change',()=>{$('commuteDate').value=$('railDate').value;$('commuteDate').dispatchEvent(new Event('change',{bubbles:true}));});
for(const id of ['railFromTime','railToTime'])$(id).addEventListener('change',renderRail);
$('railAllDay').onclick=()=>{$('railFromTime').value='';$('railToTime').value='';renderRail();};
function renderRail(){const date=$('commuteDate').value,valid=date>=data.validFrom&&date<=data.validTo,day=new Date(date+'T12:00:00Z').getUTCDay(),key=day===0?'sunday':day===6?'saturday':'weekday',field=$('railBoarding').value==='Five Ways'?'fwy':'bhm';
 $('railDate').value=date;
 $('railSelected').textContent='';$('railTableBody').replaceChildren();$('railDateStatus').textContent=date+' · '+({weekday:t('周一至周五','Monday–Friday'),saturday:t('周六','Saturday'),sunday:t('周日','Sunday')}[key])+' · '+(valid?t('本地计划时刻表','Saved scheduled timetable'):t('超出保存时刻表适用期，请查询官方','Outside saved timetable validity; check official services'));
 if(!date){$('railDateStatus').textContent=t('请选择通勤日期。','Select a travel date.');$('railTableStatus').textContent='';return;}
 if(!valid){$('railTableStatus').textContent=t('此日期不展示过期或尚未生效的班次。','No expired or not-yet-valid services shown for this date.');return;}
 const from=$('railFromTime').value,until=$('railToTime').value;
 if(from&&until&&until<from){$('railTableStatus').textContent=t('结束时间不能早于开始时间。跨日行程请分别查询两个日期。','End time must not precede start time. For overnight travel, search each date separately.');return;}
 const rows=data.days[key].filter(x=>x[field]&&(!from||x[field]>=from)&&(!until||x[field]<=until));$('railTableStatus').textContent=rows.length+' '+t('班保存记录','saved services')+' · '+(!from&&!until?t('全天','Full day'):(from||'00:00')+'–'+(until||'23:59'))+' · '+(rows.length?t('非实时运行确认','operation is not confirmed live'):t('该时段没有保存班次，可调整时间或显示全天。','No saved services in this window. Change the times or show all day.'));
 for(const x of rows){const tr=document.createElement('tr');for(const value of [x[field],x.uni,x.operator==='XC'?'CrossCountry':'West Midlands Railway']){const td=document.createElement('td');td.textContent=value;tr.append(td);}const td=document.createElement('td'),b=document.createElement('button');b.type='button';b.className='outline';b.textContent=t('选此班次','Select');b.onclick=()=>{for(const r of $('railTableBody').children)r.classList.remove('rail-picked');tr.classList.add('rail-picked');$('railSelected').textContent=$('railBoarding').value+' '+x[field]+' → University '+x.uni+' · '+t('已选计划班次，运行情况待核对；校园步行另计。','Scheduled service selected; operation unverified, campus walk additional.');};const a=document.createElement('a');a.href=data.source+'#page='+x.page;a.target='_blank';a.rel='noopener';a.textContent=t('原表','Source')+(x.note?' · '+x.note:'');td.append(b,document.createTextNode(' '),a);tr.append(td);$('railTableBody').append(tr);}
}
function walkUpdate(){if(!$('campusDirections'))return;$('routeWalkDirections').href=$('campusDirections').href;$('walkingRouteSummary').textContent=$('area').value+' → '+$('building').selectedOptions[0].textContent;}
function update(){const bus=['bus','combo'].includes(mode),train=['train','combo'].includes(mode),walking=mode==='walk';drawer.hidden=!bus;drawer.open=bus;rail.hidden=!train;label.hidden=!train;walk.hidden=!walking;const intro=panel.querySelector(':scope > p:not(.eyebrow)');if(intro)intro.hidden=!!mode;
 const desc=$('travel-flow-route').querySelector('.flow-step-intro p');desc.textContent=walking?t('直接导航至所选教学楼。','Navigate directly to the selected building.'):train?t('选择上车站，查看保存的计划班次；到校后从 University Station 步行。','Choose the boarding station and review saved scheduled services; campus walking starts at University Station.'):bus?t('在站点地图选择公交线路与上下车站。','Choose the bus line and boarding/alighting stops on the stop map.'):t('核对当前方式的路线衔接。','Check the connection for this travel mode.');
 if(train)renderRail();if(walking)walkUpdate();window.dispatchEvent(new Event('resize'));}
window.addEventListener('greengo:mode-selected',e=>{mode=e.detail.fromBuilding?'walk':e.detail.mode;update();});$('railBoarding').addEventListener('change',renderRail);$('commuteDate').addEventListener('change',renderRail);new MutationObserver(walkUpdate).observe($('campusSelection'),{childList:true,subtree:true});update();
})();
